#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# =============================================================================
# Worktree symlink-config coverage test (CC 2.1.211+ worktree.symlinkDirectories)
# =============================================================================
# The live config lives in .claude/settings.json, which is gitignored
# (.gitignore:152). It therefore cannot be reviewed, diffed, or asserted in CI.
# bin/worktree-config.sh holds the canonical list in a TRACKED file and
# generates the settings from it; this test gates that list.
#
# The failure this prevents: someone adds a workspace with its own package.json,
# never adds it to the symlink list, and every worktree from that day forward
# silently re-installs another full copy of its node_modules. The bloat is
# invisible until a disk fills. Here it is a red build instead.
#
# Assertions:
#   1. bin/worktree-config.sh exists and is executable
#   2. every tracked package.json root is EITHER in --list or in --exempt
#   3. no root is in both lists
#   4. no --list entry is absolute or contains ".." (Claude Code rejects those,
#      silently, with only a debug log line)
#   5. --apply then --check round-trips against a scratch repo
#
# Usage:
#   bash tests/worktree/test-worktree-symlink-config.sh
# =============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CONFIG_SCRIPT="$PROJECT_ROOT/bin/worktree-config.sh"

GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
NC='\033[0m'

PASS=0
FAIL=0

pass() { echo -e "${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo -e "${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }
info() { echo -e "${YELLOW}INFO${NC} $1"; }

cd "$PROJECT_ROOT"

echo ""
echo "=== 1. canonical config script ==="

if [ -x "$CONFIG_SCRIPT" ]; then
    pass "bin/worktree-config.sh exists and is executable"
else
    fail "bin/worktree-config.sh missing or not executable"
    echo "Cannot continue without the canonical list."
    exit 1
fi

SYMLINKED=$("$CONFIG_SCRIPT" --list)
EXEMPT=$("$CONFIG_SCRIPT" --exempt)

# The symlink list holds node_modules paths; reduce to the workspace root that
# owns each one so it can be compared against package.json locations.
_roots=${SYMLINKED//\/node_modules/}   # "src/hooks/node_modules" -> "src/hooks"
_roots=${_roots//node_modules/.}       # the bare repo-root entry -> "."
SYMLINK_ROOTS=$(sort -u <<< "$_roots")

echo ""
echo "=== 2. every workspace root is classified ==="

WORKSPACE_ROOTS=$(git ls-files '*package.json' \
    | grep -v node_modules \
    | sed 's#/\{0,1\}package.json$##' \
    | sed 's#^$#.#' \
    | sort -u)

UNCLASSIFIED=""
for root in $WORKSPACE_ROOTS; do
    grep -Fxq "$root" <<< "$SYMLINK_ROOTS" && continue
    grep -Fxq "$root" <<< "$EXEMPT" && continue
    UNCLASSIFIED="$UNCLASSIFIED $root"
done

if [ -z "$UNCLASSIFIED" ]; then
    pass "all $(wc -l <<< "$WORKSPACE_ROOTS" | tr -d ' ') workspace roots are classified"
else
    fail "workspace root(s) in neither --list nor --exempt:$UNCLASSIFIED"
    echo "  Every package.json root must be a deliberate choice. Edit"
    echo "  bin/worktree-config.sh: add it to SYMLINK_DIRS (it gets installed"
    echo "  and should be shared) or to EXEMPT_ROOTS with a reason comment."
fi

echo ""
echo "=== 3. no root is classified twice ==="

BOTH=""
for root in $SYMLINK_ROOTS; do
    if grep -Fxq "$root" <<< "$EXEMPT"; then
        BOTH="$BOTH $root"
    fi
done

if [ -z "$BOTH" ]; then
    pass "no overlap between --list and --exempt"
else
    fail "root(s) in BOTH lists:$BOTH"
fi

echo ""
echo "=== 4. entries survive Claude Code's path validation ==="

BAD=""
while IFS= read -r entry; do
    [ -z "$entry" ] && continue
    case "$entry" in
        /*)   BAD="$BAD $entry(absolute)" ;;
        *..*) BAD="$BAD $entry(traversal)" ;;
    esac
done <<< "$SYMLINKED"

if [ -z "$BAD" ]; then
    pass "all $(wc -l <<< "$SYMLINKED" | tr -d ' ') entries are relative and traversal-free"
else
    fail "entries Claude Code will silently skip:$BAD"
    echo "  CC rejects absolute paths and '..' segments with a debug-level log"
    echo "  line only. A rejected entry looks exactly like a working one."
fi

echo ""
echo "=== 5. --apply / --check round-trip ==="

TMP_REPO=$(mktemp -d)
cleanup() { rm -rf "$TMP_REPO"; }
trap cleanup EXIT

git -C "$TMP_REPO" init --quiet
mkdir -p "$TMP_REPO/bin"
cp "$CONFIG_SCRIPT" "$TMP_REPO/bin/worktree-config.sh"

if (cd "$TMP_REPO" && bash bin/worktree-config.sh --check > /dev/null 2>&1); then
    fail "--check passed with no settings file (should fail closed)"
else
    pass "--check fails when .claude/settings.json is absent"
fi

if (cd "$TMP_REPO" && bash bin/worktree-config.sh --apply > /dev/null); then
    pass "--apply writes the settings file"
else
    fail "--apply failed"
fi

if (cd "$TMP_REPO" && bash bin/worktree-config.sh --check > /dev/null); then
    pass "--check passes immediately after --apply"
else
    fail "--check disagrees with what --apply just wrote"
fi

# Drift detection: mutate the generated file, --check must catch it.
if command -v jq > /dev/null; then
    jq '.worktree.symlinkDirectories = ["node_modules"]' \
        "$TMP_REPO/.claude/settings.json" > "$TMP_REPO/.claude/settings.json.tmp"
    mv "$TMP_REPO/.claude/settings.json.tmp" "$TMP_REPO/.claude/settings.json"
    if (cd "$TMP_REPO" && bash bin/worktree-config.sh --check > /dev/null 2>&1); then
        fail "--check passed on a hand-truncated list (drift undetected)"
    else
        pass "--check detects drift in the live settings file"
    fi

    # Unrelated keys must survive a re-apply.
    jq '. + {model: "opus"}' "$TMP_REPO/.claude/settings.json" \
        > "$TMP_REPO/.claude/settings.json.tmp"
    mv "$TMP_REPO/.claude/settings.json.tmp" "$TMP_REPO/.claude/settings.json"
    (cd "$TMP_REPO" && bash bin/worktree-config.sh --apply > /dev/null)
    if [ "$(jq -r '.model' "$TMP_REPO/.claude/settings.json")" = "opus" ]; then
        pass "--apply preserves unrelated settings keys"
    else
        fail "--apply clobbered an unrelated settings key"
    fi
else
    info "jq unavailable - skipped drift and key-preservation checks"
fi

echo ""
echo "=== 6. worktree-reclaim.sh refuses to no-op ==="

# The bug this catches, hit for real: worktree-reclaim.sh resolved the canonical
# list as "$MAIN/bin/worktree-config.sh". The main worktree is routinely parked
# on a branch that predates that file, so the lookup failed. `mapfile < <(cmd)`
# does not abort under `set -e`, so the directory list came back EMPTY, every
# loop body was skipped, and the script printed "links: 0 ... reclaims: 0 MB"
# and exited 0. A silent no-op that reads as success.
RECLAIM="$PROJECT_ROOT/bin/worktree-reclaim.sh"

if [ -x "$RECLAIM" ]; then
    if grep -q 'BASH_SOURCE' "$RECLAIM"; then
        pass "reclaim resolves the canonical list next to itself, not under \$MAIN"
    else
        fail "reclaim still resolves the canonical list from the main worktree"
        echo "  The main worktree is often on a branch without bin/worktree-config.sh."
    fi

    # Behavioural check: point it at an empty list and require a LOUD failure.
    STUB_DIR=$(mktemp -d)
    cp "$RECLAIM" "$STUB_DIR/worktree-reclaim.sh"
    printf '#!/bin/bash\nexit 0\n' > "$STUB_DIR/worktree-config.sh"
    chmod +x "$STUB_DIR"/*.sh
    if (cd "$PROJECT_ROOT" && bash "$STUB_DIR/worktree-reclaim.sh" --dry-run > /dev/null 2>&1); then
        fail "reclaim exited 0 on an empty directory list (silent no-op)"
    else
        pass "reclaim exits non-zero rather than silently doing nothing"
    fi
    rm -rf "$STUB_DIR"
else
    info "bin/worktree-reclaim.sh absent - skipped no-op checks"
fi

echo ""
echo "=== Results ==="
echo -e "${GREEN}Passed: $PASS${NC}"
if [ "$FAIL" -gt 0 ]; then
    echo -e "${RED}Failed: $FAIL${NC}"
    exit 1
fi
echo -e "${GREEN}Failed: 0${NC}"
echo -e "${GREEN}All worktree symlink-config tests passed.${NC}"
